import z3

def solve_golfers():
    W = 7
    G = 10
    S = 3
    P = G * S

    solver = z3.Solver()

    # x[w][p] = group of player p in week w
    x = [[z3.Int(f"x_{w}_{p}") for p in range(P)] for w in range(W)]

    for w in range(W):
        for p in range(P):
            solver.add(x[w][p] >= 0, x[w][p] < G)

    # Each group has exactly S players
    for w in range(W):
        for g in range(G):
            solver.add(z3.PbEq([(x[w][p] == g, 1) for p in range(P)], S))

    # No two players in the same group more than once
    for p1 in range(P):
        for p2 in range(p1 + 1, P):
            solver.add(z3.PbLe([(x[w][p1] == x[w][p2], 1) for w in range(W)], 1))

    # Symmetry breaking
    # Week 0: player p is in group p // S
    for p in range(P):
        solver.add(x[0][p] == p // S)

    # Player 0 is always in group 0
    for w in range(1, W):
        solver.add(x[w][0] == 0)

    # Week 1: players 0, 3, 6 are in group 0
    solver.add(x[1][3] == 0)
    solver.add(x[1][6] == 0)

    print("Solving...")
    if solver.check() == z3.sat:
        m = solver.model()
        res = []
        for w in range(W):
            for p in range(P):
                res.append(m[x[w][p]].as_long())
        print("SAT")
        print(res)
    else:
        print("UNSAT")

solve_golfers()

import time
from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType

def solve_sgp():
    W = 7
    G = 10
    S = 3
    P = G * S

    # Variables: x[w][p][g] is true if player p is in group g in week w
    def var(w, p, g):
        return w * P * G + p * G + g + 1

    solver = Glucose4()

    # Each player is in exactly one group per week
    for w in range(W):
        for p in range(P):
            vars_p = [var(w, p, g) for g in range(G)]
            solver.add_clause(vars_p)
            for i in range(G):
                for j in range(i + 1, G):
                    solver.add_clause([-vars_p[i], -vars_p[j]])

    # Each group has exactly S players
    for w in range(W):
        for g in range(G):
            vars_g = [var(w, p, g) for p in range(P)]
            cnf = CardEnc.equals(lits=vars_g, bound=S, encoding=EncType.seqcounter, top_id=solver.nof_vars())
            for clause in cnf.clauses:
                solver.add_clause(clause)

    # No two players in the same group more than once
    # For each pair of players, they can be in the same group at most once across all weeks
    # Let y[w][p1][p2] be true if p1 and p2 are in the same group in week w
    # y[w][p1][p2] <-> OR_g (x[w][p1][g] AND x[w][p2][g])
    # Actually, we can just say: sum_w y[w][p1][p2] <= 1

    top_id = solver.nof_vars()
    for p1 in range(P):
        for p2 in range(p1 + 1, P):
            y_vars = []
            for w in range(W):
                y_w = top_id + 1
                top_id += 1
                y_vars.append(y_w)

                # y_w -> OR_g (x[w][p1][g] AND x[w][p2][g])
                # If x[w][p1][g] and x[w][p2][g] are both true, then y_w must be true
                for g in range(G):
                    solver.add_clause([-var(w, p1, g), -var(w, p2, g), y_w])

            # sum y_vars <= 1
            for i in range(W):
                for j in range(i + 1, W):
                    solver.add_clause([-y_vars[i], -y_vars[j]])

    # Symmetry breaking
    # Week 0: player p is in group p // S
    for p in range(P):
        solver.add_clause([var(0, p, p // S)])

    # Player 0 is always in group 0
    for w in range(1, W):
        solver.add_clause([var(w, 0, 0)])

    # Week 1: players 0, 3, 6 are in group 0
    solver.add_clause([var(1, 3, 0)])
    solver.add_clause([var(1, 6, 0)])

    print("Solving...")
    start = time.time()
    if solver.solve():
        print("SAT", time.time() - start)
        model = solver.get_model()
        res = []
        for w in range(W):
            for p in range(P):
                for g in range(G):
                    if model[var(w, p, g) - 1] > 0:
                        res.append(g)
        print(res)
    else:
        print("UNSAT", time.time() - start)

